BEGIN;
CREATE FUNCTION pg_temp.pay_assert(ok boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'TEST FAILED: %',label;END IF;END$$;
DO $$
DECLARE u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();root_id uuid:=gen_random_uuid();hid uuid:=gen_random_uuid();cid uuid;chat_id uuid:=gen_random_uuid();pay_id uuid:=gen_random_uuid();again uuid:=gen_random_uuid();q jsonb;unknown_q jsonb;quote_id uuid;claim jsonb;outcome jsonb;inp jsonb;p jsonb;denied boolean;payment jsonb;items jsonb;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data)VALUES(u,'chat-payment-'||u||'@example.invalid',now(),'{}'),(v,'chat-payment-'||v||'@example.invalid',now(),'{}');
 inp:=jsonb_build_object('city','Shanghai','date',current_date+80,'guests',1,'prompt','Museum local food matcha','days',3,'dayStart','09:00','dayEnd','20:00','transport','walk');
 p:='{"summary":"Three visits","stops":[{"id":"amap_paymuseum","dayIndex":1,"start":"09:00","end":"10:00","reason":"Museum"},{"id":"amap_paylunch","dayIndex":2,"start":"12:00","end":"13:00","reason":"Local lunch"},{"id":"amap_paymatcha","dayIndex":3,"start":"15:00","end":"16:00","reason":"Matcha"}]}';
 INSERT INTO journey_hub.trip_history(id,user_id,input,place_ids)VALUES(root_id,u,inp,ARRAY['amap_paymuseum','amap_paylunch','amap_paymatcha']);
 INSERT INTO journey_hub.trip_history(id,user_id,parent_id,input,place_ids,plan)VALUES(hid,u,root_id,inp,ARRAY['amap_paymuseum','amap_paylunch','amap_paymatcha'],p);
 outcome:=public.journeyhub_care_confirm(u,'history',hid);cid:=(outcome->>'id')::uuid;
 items:='[{"stopId":"amap_paymuseum","kind":"ticket","unitMinor":4000,"displayTitle":"Museum"},{"stopId":"amap_paylunch","kind":"restaurant","unitMinor":5000,"displayTitle":"Local lunch"},{"stopId":"amap_paymatcha","kind":"cafe","unitMinor":2000,"displayTitle":"Matcha"}]';
 q:=public.journeyhub_demo_quote_save(u,'history',hid,items);quote_id:=(q->>'id')::uuid;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='DEMO_QUOTE_NOT_FOUND';END;
 PERFORM pg_temp.pay_assert(denied,'unoffered quote cannot be silently charged');
 PERFORM public.journeyhub_care_chat_start(u,cid,chat_id,'Prepare virtual payment',1);claim:=public.journeyhub_care_chat_claim(u,cid,chat_id);
 outcome:=public.journeyhub_care_chat_complete(u,cid,chat_id,(claim->>'lease')::uuid,'Review the virtual payment before confirming.',NULL,'[]',jsonb_build_object('payment',jsonb_build_object('quoteId',quote_id),'fakeTotal',1));
 SELECT m->'paymentAction'INTO payment FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE m->>'id'=chat_id||':assistant';
 PERFORM pg_temp.pay_assert(payment->>'status'='insufficient_funds'AND payment->>'totalMinor'='11000'AND payment->>'shortfallMinor'='11000','quote derives actual total and shortfall, ignoring model values');
 PERFORM pg_temp.pay_assert(NOT EXISTS(SELECT FROM journey_hub.demo_ledger WHERE user_id=u),'preparing never tops up or pays');
 unknown_q:=public.journeyhub_demo_quote_save(u,'history',hid,jsonb_set(jsonb_set(items,'{0,kind}','"unavailable"'),'{0,unitMinor}','0'));
 payment:=journey_hub.care_chat_payment_action(u,cid,jsonb_build_object('payment',jsonb_build_object('quoteId',unknown_q->>'id')));
 PERFORM pg_temp.pay_assert(payment->>'status'='not_eligible'AND payment#>>'{items,0,status}'='unavailable','unknown eligibility cannot be shown as available or free');
 UPDATE journey_hub.trip_care SET plan=jsonb_set(plan,'{summary}','"Changed schedule"')WHERE id=cid;
 payment:=journey_hub.care_chat_payment_action(u,cid,jsonb_build_object('payment',jsonb_build_object('quoteId',quote_id)));
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='DEMO_QUOTE_STALE';END;
 PERFORM pg_temp.pay_assert(denied AND payment->>'status'='stale','changed itinerary invalidates offered quote at final payment');
 UPDATE journey_hub.trip_care SET plan=p WHERE id=cid;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='DEMO_INSUFFICIENT_FUNDS';END;
 PERFORM pg_temp.pay_assert(denied AND NOT EXISTS(SELECT FROM journey_hub.care_chat_payments WHERE user_id=u),'insufficient funds yields no receipt or charge');
 PERFORM public.journeyhub_demo_wallet_topup(u,20000,gen_random_uuid());
 outcome:=public.journeyhub_care_chat_read(u,cid);
 PERFORM pg_temp.pay_assert(EXISTS(SELECT FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE m#>>'{paymentAction,status}'='ready'AND m#>>'{paymentAction,balanceMinor}'='20000'),'quote becomes ready only after explicit wallet topup');
 UPDATE journey_hub.demo_quotes SET expires_at=now()-interval '1 second'WHERE id=quote_id;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='DEMO_QUOTE_EXPIRED';END;
 PERFORM pg_temp.pay_assert(denied AND (SELECT balance_minor=20000 FROM journey_hub.demo_wallets WHERE user_id=u),'expired quote cannot debit');
 UPDATE journey_hub.demo_quotes SET expires_at=now()+interval '30 minutes'WHERE id=quote_id;
 denied:=false;BEGIN PERFORM public.journeyhub_care_chat_payment(v,cid,gen_random_uuid(),quote_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='CARE_CHAT_NOT_FOUND';END;
 PERFORM pg_temp.pay_assert(denied,'foreign account cannot confirm another owner quote');
 outcome:=public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);
 SELECT m->'paymentReceipt'INTO payment FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE m->>'id'=pay_id||':payment';
 PERFORM pg_temp.pay_assert(payment->>'totalMinor'='11000'AND payment->>'balanceMinor'='9000'AND jsonb_array_length(payment->'bookingIds')=3,'payment saves canonical IDs and captured postpayment balance');
 PERFORM pg_temp.pay_assert((SELECT count(*)=3 FROM journey_hub.bookings b JOIN journey_hub.travelers t ON t.traveler_id=b.traveler_id WHERE t.auth_user_id=u AND b.payment_status='simulated_paid'),'existing canonical booking path is reused');
 PERFORM public.journeyhub_care_chat_payment(u,cid,pay_id,quote_id);PERFORM public.journeyhub_care_chat_payment(u,cid,gen_random_uuid(),quote_id);
 PERFORM pg_temp.pay_assert((SELECT balance_minor=9000 FROM journey_hub.demo_wallets WHERE user_id=u)AND(SELECT count(*)=1 FROM journey_hub.care_chat_payments WHERE care_id=cid),'same or different replay request cannot duplicate debit/receipt');
 PERFORM public.journeyhub_demo_wallet_topup(u,1000,gen_random_uuid());
 outcome:=public.journeyhub_care_chat_read(u,cid);
 PERFORM pg_temp.pay_assert(EXISTS(SELECT FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE m->>'id'=pay_id||':payment'AND m#>>'{paymentReceipt,balanceMinor}'='9000'),'receipt keeps historical balance after later wallet changes');
 -- Already-paid historical trips return saved receipts without demo_source/date validation.
 UPDATE journey_hub.trip_care SET input=jsonb_set(input,'{date}',to_jsonb((current_date-5)::text))WHERE id=cid;
 PERFORM public.journeyhub_care_chat_start(u,cid,again,'Have I already paid?',1);claim:=public.journeyhub_care_chat_claim(u,cid,again);
 outcome:=public.journeyhub_care_chat_complete(u,cid,again,(claim->>'lease')::uuid,'These existing reservations are already paid.',NULL,'[]',jsonb_build_object('payment',jsonb_build_object('quoteId',quote_id)));
 PERFORM pg_temp.pay_assert(EXISTS(SELECT FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE m->>'id'=again||':assistant'AND m#>>'{paymentAction,status}'='paid'AND m#>>'{paymentReceipt,totalMinor}'='11000'),'past paid quote renders actual receipt without new payment');
 PERFORM pg_temp.pay_assert(NOT has_function_privilege('authenticated','public.journeyhub_care_chat_payment(uuid,uuid,uuid,uuid)','EXECUTE')AND NOT has_table_privilege('authenticated','journey_hub.care_chat_payments','SELECT'),'payment stays service-only');
 RAISE NOTICE 'PASS virtual chat payment: owned quote, funds/expiry checks, explicit confirmation, canonical receipts, duplicate protection and historical paid reuse';
END$$;
DO $$
DECLARE u uuid:=gen_random_uuid();root_id uuid:=gen_random_uuid();hid uuid:=gen_random_uuid();cid uuid;inp jsonb;p jsonb;swap jsonb;proposal_id uuid:=gen_random_uuid();outcome jsonb;denied boolean;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at,raw_user_meta_data)VALUES(u,'chat-days-'||u||'@example.invalid',now(),'{}');
 inp:=jsonb_build_object('city','Shanghai','date',current_date+80,'guests',1,'prompt','Three saved days','days',4,'dayStart','09:00','dayEnd','20:00','transport','walk');
 p:='{"summary":"Legacy three populated days out of four","stops":[{"id":"amap_dayone","dayIndex":1,"start":"09:00","end":"10:00","reason":"First visit"},{"id":"amap_daytwo","dayIndex":2,"start":"09:00","end":"10:00","reason":"Second visit"},{"id":"amap_daythree","dayIndex":3,"start":"09:00","end":"10:00","reason":"Third visit"}]}';
 INSERT INTO journey_hub.trip_history(id,user_id,input,place_ids)VALUES(root_id,u,inp,ARRAY['amap_dayone','amap_daytwo','amap_daythree']);
 INSERT INTO journey_hub.trip_history(id,user_id,parent_id,input,place_ids,plan)VALUES(hid,u,root_id,inp,ARRAY['amap_dayone','amap_daytwo','amap_daythree'],p);
 outcome:=public.journeyhub_care_confirm(u,'history',hid);cid:=(outcome->>'id')::uuid;
 swap:=jsonb_set(jsonb_set(p,'{stops,0,dayIndex}','2'),'{stops,1,dayIndex}','1');
 PERFORM public.journeyhub_care_update(u,cid,1,NULL,jsonb_build_object('id',proposal_id,'revision',1,'affectedDays','[1,2]'::jsonb,'canApply',true,'expiresAt',now()+interval '30 minutes','plan',swap));
 outcome:=public.journeyhub_care_chat_apply(u,cid,proposal_id,gen_random_uuid());
 PERFORM pg_temp.pay_assert(EXISTS(SELECT FROM jsonb_array_elements(outcome#>'{conversation,messages}')m WHERE jsonb_array_length(m->'itineraries')=2 AND m->'itinerary'='null'::jsonb),'two-day swap persists two actual complete-day snapshots');
 proposal_id:=gen_random_uuid();swap:=jsonb_set(swap,'{stops,2,dayIndex}','2');swap:=jsonb_set(jsonb_set(swap,'{stops,2,start}','"15:00"'),'{stops,2,end}','"16:00"');
 PERFORM public.journeyhub_care_update(u,cid,2,NULL,jsonb_build_object('id',proposal_id,'revision',2,'canApply',true,'expiresAt',now()+interval '30 minutes','plan',swap));
 denied:=false;BEGIN PERFORM public.journeyhub_care_accept(u,cid,proposal_id);EXCEPTION WHEN OTHERS THEN denied:=SQLERRM='CARE_UNSAFE_ADJUSTMENT';END;
 PERFORM pg_temp.pay_assert(denied,'legacy adjustment cannot make another day empty');
 RAISE NOTICE 'PASS multi-day snapshots and non-worsening legacy day coverage';
END$$;
ROLLBACK;
